WITH flattened_attrs AS (SELECT id, host, log_ts, latency_ms, COALESCE(context['region'], 'direct') AS region_or_default, context['region'] AS region, FROM_JSON(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').retries AS retry_count FROM app_logs) SELECT CASE WHEN latency_ms >= 2001 THEN 'HIGH' ELSE 'LOW' END AS latency_ms_tier, (UNIX_TIMESTAMP(MAX(log_ts)) - UNIX_TIMESTAMP(MIN(log_ts))) / 60 AS span_minutes, BIT_OR(latency_ms) AS latency_ms_bit_or, SIZE(COLLECT_SET(host)) AS num_hosts, BIT_OR(latency_ms) AS latency_ms_bit_or_2, COUNT(*) AS event_count, STDDEV_SAMP(latency_ms) AS latency_ms_stddev FROM flattened_attrs GROUP BY CASE WHEN latency_ms >= 2001 THEN 'HIGH' ELSE 'LOW' END
